SELECT decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0), NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))- decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUS_A.FINISH_AMT,0)) proAvailableCash FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN OPT_TARGET_INFO ON ETR_ENTRUST_ADD.ASSET_TYPE_10 = OPT_TARGET_INFO.TARGET_ID
AND ETR_ENTRUST.ENTRUST_DATE = to_date(#{entrustDate},'yyyy-mm-dd')
AND ETR_ENTRUST.PORTFOLIO_ID = #{portfolioId}
AND ETR_ENTRUST.FINPROD_ID = #{finprodId}
AND ETR_ENTRUST.ENTRUST_ID = #{entrustId}
union all SELECT decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0), NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))- decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),'F10',NVL(ETR_FINISH_STATUS_A.FINISH_AMT * 100,0),NVL(ETR_FINISH_STATUS_A.FINISH_AMT,0)) proAvailableCash FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID LEFT JOIN (SELECT ETR_FINISH_STATUS.ENTRUST_ID,sum(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) ETR_FINISH_STATUS_A ON ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID
AND ETR_ENTRUST.ENTRUST_DATE = to_date(#{entrustDate},'yyyy-mm-dd')
AND ETR_ENTRUST.PORTFOLIO_ID = #{portfolioId}
AND ETR_ENTRUST.FINPROD_ID = #{finprodId}
AND ETR_ENTRUST.ENTRUST_ID = #{entrustId}
